function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

// Pasar tiempos a nano
const startTime = $input.first().json.query_start_time_ms * 1000000;
const now = Date.now();
const endTime = now * 1000000;

// Generamos los IDs basándonos en UUID v4
const uuidTrace = generateUUID(); // Formato: xxxxxxxx-xxxx-4xxx...
const uuidSpan = generateUUID();

// OpenTelemetry exige Hexadecimal seguido sin guiones
// TraceID: 32 chars (quitamos los guiones al UUID completo)
const traceId = uuidTrace.replace(/-/g, ''); 

// SpanID: 16 chars (tomamos solo los primeros 16 chars del segundo UUID sin guiones)
// Nota: Un SpanID debe ser de 64 bits (16 hex chars).
const spanId = uuidSpan.replace(/-/g, '').substring(0, 16);

return {
  json: {
    otel_trace_id: traceId,
    otel_span_id: spanId,
    start_time: startTime,
    end_time: endTime
  }
};
